// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address addr, uint256 value) public {
        vm.assume(value > 0);
        vm.assume(addr != address(0));
        vm.deal(addr, value);
        vm.prank(addr);
        uint256 balanceBefore = address(c).balance;
        c.deposit{value: value}();
        uint256 balanceAfter = address(c).balance;
        assertTrue(balanceAfter == balanceBefore + value);
    }
}

